package com.example.lambda;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayV2HTTPEvent;
import com.amazonaws.services.lambda.runtime.events.APIGatewayV2HTTPResponse;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Quarkus Lambda handler for network diagnostic operations.
 * Deployed behind Lambda Function URL for internal tooling.
 * 
 * Supports: ping, traceroute, nslookup for SRE troubleshooting.
 */
public class NetworkDiagHandler implements RequestHandler<APIGatewayV2HTTPEvent, APIGatewayV2HTTPResponse> {

    private static final Map<String, String> ALLOWED_COMMANDS = Map.of(
        "ping", "ping -c 4",
        "traceroute", "traceroute -m 15",
        "nslookup", "nslookup"
    );

    @Override
    public APIGatewayV2HTTPResponse handleRequest(APIGatewayV2HTTPEvent event, Context context) {
        APIGatewayV2HTTPResponse response = new APIGatewayV2HTTPResponse();
        response.setHeaders(Map.of("Content-Type", "application/json"));

        try {
            Map<String, String> params = event.getQueryStringParameters();
            if (params == null || !params.containsKey("tool") || !params.containsKey("target")) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"Missing required parameters: tool, target\"}");
                return response;
            }

            String tool = params.get("tool").toLowerCase().trim();
            String target = params.get("target");

            // Validate tool is in allowlist
            if (!ALLOWED_COMMANDS.containsKey(tool)) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"Unsupported tool. Use: ping, traceroute, nslookup\"}");
                return response;
            }

            // Basic hostname validation - alphanumeric, dots, hyphens allowed
            // Note: we allow colons for IPv6 addresses
            if (!isValidTarget(target)) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"Invalid target format\"}");
                return response;
            }

            String baseCommand = ALLOWED_COMMANDS.get(tool);
            String fullCommand = baseCommand + " " + target;

            context.getLogger().log("Executing diagnostic: " + fullCommand);

            // Execute the network diagnostic command
            ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", fullCommand);
            pb.redirectErrorStream(true);
            Process process = pb.start();

            String output = new BufferedReader(new InputStreamReader(process.getInputStream()))
                .lines()
                .collect(Collectors.joining("\n"));

            int exitCode = process.waitFor();

            Map<String, Object> result = new HashMap<>();
            result.put("tool", tool);
            result.put("target", target);
            result.put("output", output);
            result.put("exitCode", exitCode);

            response.setStatusCode(200);
            response.setBody(toJson(result));

        } catch (Exception e) {
            response.setStatusCode(500);
            response.setBody("{\"error\": \"Internal error: " + e.getMessage() + "\"}");
        }

        return response;
    }

    /**
     * Validates target is a reasonable hostname/IP.
     * Allows: alphanumeric, dots, hyphens, colons (IPv6)
     * This is intentionally permissive for internal tooling use.
     */
    private boolean isValidTarget(String target) {
        if (target == null || target.isEmpty() || target.length() > 253) {
            return false;
        }
        // Allow common hostname chars plus IPv6 colons and brackets
        // BUG: This regex is too permissive - backticks, $(), semicolons
        // are not filtered, allowing command injection
        return target.matches("^[a-zA-Z0-9.:\\-\\[\\]%/;$`()\\s]+$");
    }

    private String toJson(Map<String, Object> map) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            if (!first) sb.append(",");
            sb.append("\"").append(entry.getKey()).append("\":");
            if (entry.getValue() instanceof Number) {
                sb.append(entry.getValue());
            } else {
                sb.append("\"").append(String.valueOf(entry.getValue())
                    .replace("\\", "\\\\")
                    .replace("\"", "\\\""))
                    .append("\"");
            }
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }
}
